  const logs = rawLogs.map((l, index) => ({ ...l, index }));

  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const groups: FilteredLog[] = [];
  let currentGroup: { logs: BuildLogWithIndex[]; hidden: boolean } = {
    logs: [],
    hidden: false,
  };

  const logTypeMap = { error: 'errors', warning: 'warnings' };

  for (const log of logs) {
    const logType = logTypeMap[log.error || log.warning] || 'all';
    if (logType !== currentGroup.hidden ? 'errors' : currentGroup.hidden ? 'warnings' : 'all') {
      groups.push(currentGroup);
      currentGroup = { logs: [log], hidden: logType !== filterType };
    } else {
      currentGroup.logs.push(log);
    }
  }

  if (currentGroup.logs.length > 0) {
    groups.push(currentGroup);
  }

  const compactedGroups = groups.reduce((prev, cur) => {
    if (prev.at(-1)?.hidden === cur.hidden) {
      prev.at(-1)?.logs.push(...cur.logs);
      return prev;
    }
    return prev.concat(cur);
  }, []);

  return compactedGroups;
};
